#!/bin/bash
# The Homebrew formula for the sparewall CLI (Formula/sparewall.rb in
# sparewall/homebrew-tap), for one release, from its SHA256SUMS: a block
# for each platform the release has a CLI tarball for.
#
#   homebrew-formula.sh VERSION SHA256SUMS [BASE_URL] > sparewall.rb
#
# BASE_URL is where the tarballs are (default: the release's downloads);
# tests point it at local files.
set -euo pipefail
v=${1:?usage: homebrew-formula.sh VERSION SHA256SUMS [BASE_URL]}
sums=${2:?usage: homebrew-formula.sh VERSION SHA256SUMS [BASE_URL]}
base=${3:-https://github.com/sparewall/sparewall/releases/download/v$v}

# The block for one tarball, or nothing if the release lacks it.
asset() { # os-arch block-name
    local f=sparewall-$v-$1.tar.gz sum
    sum=$(awk -v f="$f" '$2 == f || $2 == "*" f { print $1 }' "$sums")
    [ -n "$sum" ] || return 0
    cat <<RUBY
    $2 do
      url "$base/$f"
      sha256 "$sum"
    end
RUBY
}

os() { # on_macos|on_linux, then os-arch block-name pairs
    local name=$1 body
    shift
    body=$(while [ $# -gt 0 ]; do asset "$1" "$2"; shift 2; done)
    [ -n "$body" ] || return 0
    printf '  %s do\n%s\n  end\n\n' "$name" "$body"
}

blocks=$(
    os on_macos aarch64-darwin on_arm x86_64-darwin on_intel
    os on_linux x86_64-linux on_intel aarch64-linux on_arm
)
[ -n "$blocks" ] || { echo "$sums lists no CLI tarball for $v" >&2; exit 1; }

cat <<RUBY
# Generated by .github/homebrew-formula.sh in sparewall/sparewall for each
# release; edits here are overwritten.
class Sparewall < Formula
  desc "CLI for Sparewall, an image-based Linux firewall"
  homepage "https://sparewall.org"
  version "$v"
  license "GPL-3.0-only"

$blocks

  def install
    bin.install "sparewall"
    generate_completions_from_executable(bin/"sparewall", "completion")
  end

  def post_install
    return unless OS.mac?

    # The macOS build is signed ad hoc, not notarized: should the download
    # carry the quarantine attribute, macOS would refuse to run it.
    # Homebrew installs the binary read-only, and removing an attribute
    # needs write permission.
    f = prefix/"bin/sparewall"
    mode = f.stat.mode
    f.chmod(mode | 0200)
    quiet_system "xattr", "-d", "com.apple.quarantine", f
    f.chmod(mode)
  end

  test do
    assert_equal "sparewall #{version}", shell_output("#{bin}/sparewall --version").strip
  end
end
RUBY
